/*  Реквизит: таймер обратного отсчёта (кино / квест / вечеринка)
 *  Uno R3 + LCD1602 I2C + клавиатура 4x4 + буззер + 2 LED
 *  Никаких инициаторов и пиротехники — только свет и звук.
 */

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <Keypad.h>
#include "secrets.h"

LiquidCrystal_I2C lcd(0x27, 16, 2);   // если пусто — поменяйте на 0x3F

// ---------- пины ----------
const uint8_t PIN_BUZZER    = 8;
const uint8_t PIN_LED_RED   = 9;
const uint8_t PIN_LED_GREEN = 12;
const uint8_t PIN_START_BTN = A0;     // кнопка на GND, INPUT_PULLUP

// ---------- клавиатура ----------
const byte ROWS = 4, COLS = 4;
char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};
byte rowPins[ROWS] = {2, 3, 4, 5};
byte colPins[COLS] = {6, 7, 10, 11};
Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

// ---------- сценарий ----------
const char     CODE[5]   = "1234";    // код обезвреживания
const uint8_t  CODE_LEN  = 4;
const uint32_t START_MS  = 60000UL;   // стартовое время, мс
const uint32_t PENALTY_MS = 10000UL;  // штраф за неверный код

enum State { IDLE, RUNNING, DEFUSED, BOOM };
State state = IDLE;

uint32_t endAt = 0, lastTick = 0, lastSiren = 0;
uint16_t lastShownSec = 0xFFFF;
bool sirenHigh = false;

char entry[CODE_LEN + 1];
uint8_t entryLen = 0;

// ---------- вспомогательное ----------
void beep(uint16_t freq, uint16_t ms) { tone(PIN_BUZZER, freq, ms); }

void clearEntry() { entryLen = 0; entry[0] = '\0'; }

void drawTime(uint16_t sec) {
  char buf[17];
  snprintf(buf, sizeof(buf), "T %02u:%02u     ", (unsigned)(sec / 60), (unsigned)(sec % 60));
  lcd.setCursor(0, 0);
  lcd.print(buf);
}

void drawEntry() {
  char mask[CODE_LEN + 1];
  for (uint8_t i = 0; i < CODE_LEN; i++) mask[i] = (i < entryLen) ? '*' : '-';
  mask[CODE_LEN] = '\0';
  char buf[17];
  snprintf(buf, sizeof(buf), "CODE %s   ", mask);
  lcd.setCursor(0, 1);
  lcd.print(buf);
}

bool startPressed() {                 // фронт нажатия, без delay
  static bool prev = false;
  bool now = (digitalRead(PIN_START_BTN) == LOW);
  bool edge = now && !prev;
  prev = now;
  return edge;
}

// ---------- переходы состояний ----------
void resetToIdle() {
  state = IDLE;
  noTone(PIN_BUZZER);
  digitalWrite(PIN_LED_RED, LOW);
  digitalWrite(PIN_LED_GREEN, LOW);
  clearEntry();
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("READY  T=");
  lcd.print(START_MS / 1000);
  lcd.print("s   ");
  lcd.setCursor(0, 1);
  lcd.print("A=arm         ");
}

void startCountdown() {
  state = RUNNING;
  endAt = millis() + START_MS;
  lastTick = millis();
  lastShownSec = 0xFFFF;
  clearEntry();
  digitalWrite(PIN_LED_RED, LOW);
  digitalWrite(PIN_LED_GREEN, LOW);
  lcd.clear();
  drawEntry();
  beep(2400, 120);                    // «отсчёт пошёл»
}

void goDefused() {
  state = DEFUSED;
  noTone(PIN_BUZZER);
  digitalWrite(PIN_LED_RED, LOW);
  clearEntry();
  lcd.clear();
  lcd.setCursor(2, 0);
  lcd.print("DEFUSED");
  lcd.setCursor(0, 1);
  lcd.print("A = reset     ");
  tone(PIN_BUZZER, 1200, 90); delay(110);
  tone(PIN_BUZZER, 1600, 90); delay(110);
  tone(PIN_BUZZER, 2000, 140); delay(160);
  noTone(PIN_BUZZER);
}

void goBoom() {
  state = BOOM;
  noTone(PIN_BUZZER);
  digitalWrite(PIN_LED_GREEN, LOW);
  clearEntry();
  lcd.clear();
  lcd.setCursor(4, 0);
  lcd.print("BOOM!");
  lcd.setCursor(0, 1);
  lcd.print("A = reset     ");
  sirenHigh = false;
  lastSiren = 0;
}

void errorSound() {                   // неверный код
  tone(PIN_BUZZER, 300, 150); delay(170);
  tone(PIN_BUZZER, 200, 250); delay(270);
  noTone(PIN_BUZZER);
}

void checkCode() {
  if (entryLen == CODE_LEN && strncmp(entry, CODE, CODE_LEN) == 0) {
    goDefused();
    return;
  }
  clearEntry();
  drawEntry();
  errorSound();
  endAt -= PENALTY_MS;                // штраф
  if ((int32_t)(millis() - endAt) >= 0) { goBoom(); return; }
  lastShownSec = 0xFFFF;              // заставим перерисовать время
  lcd.setCursor(0, 0);
  lcd.print("WRONG!  -10s  ");
}

// ---------- обработка ввода ----------
void handleKeys() {
  bool btn = startPressed();
  char k = keypad.getKey();

  if (state == IDLE) {
    if (k == 'A' || btn) startCountdown();
    return;
  }

  if (state == RUNNING) {
    if (k >= '0' && k <= '9') {
      if (entryLen < CODE_LEN) {
        entry[entryLen++] = k;
        entry[entryLen] = '\0';
        beep(2200, 30);
        drawEntry();
      }
    } else if (k == '*') {
      clearEntry();
      drawEntry();
      beep(1000, 50);
    } else if (k == '#') {
      checkCode();
    }
    return;
  }

  if (state == DEFUSED || state == BOOM) {
    if (k == 'A' || btn) resetToIdle();
  }
}

// ---------- циклы состояний ----------
void updateRun() {
  uint32_t now = millis();
  if ((int32_t)(now - endAt) >= 0) { goBoom(); return; }

  uint32_t remain = endAt - now;
  uint16_t sec = (uint16_t)((remain + 999) / 1000);
  if (sec != lastShownSec) { lastShownSec = sec; drawTime(sec); }

  // тик ускоряется по мере приближения к нулю: 1000 мс → 60 мс
  uint16_t period = (uint16_t)constrain(
      map((long)remain, 0L, (long)START_MS, 60L, 1000L), 60L, 1000L);

  if (now - lastTick >= period) {
    lastTick = now;
    uint16_t f = (remain < 10000UL) ? 2600 : 1800;   // ниже 10 с — выше и злее
    beep(f, 20);
    if (remain < 10000UL) digitalWrite(PIN_LED_RED, !digitalRead(PIN_LED_RED));
  }
}

void updateBoom() {
  uint32_t now = millis();
  if (now - lastSiren >= 180) {
    lastSiren = now;
    sirenHigh = !sirenHigh;
    tone(PIN_BUZZER, sirenHigh ? 1600 : 900);
    digitalWrite(PIN_LED_RED, sirenHigh ? HIGH : LOW);
  }
}

// ---------- setup / loop ----------
void setup() {
  pinMode(PIN_BUZZER, OUTPUT);
  pinMode(PIN_LED_RED, OUTPUT);
  pinMode(PIN_LED_GREEN, OUTPUT);
  pinMode(PIN_START_BTN, INPUT_PULLUP);
  digitalWrite(PIN_LED_RED, LOW);
  digitalWrite(PIN_LED_GREEN, LOW);

  lcd.init();          // в старой версии библиотеки: lcd.begin();
  lcd.backlight();
  resetToIdle();
}

void loop() {
  handleKeys();
  switch (state) {
    case RUNNING: updateRun();  break;
    case BOOM:    updateBoom(); break;
    default: break;             // IDLE / DEFUSED рисуются один раз
  }
}
